$('undo').onclick=()=>{if(walking||checking||!blueprintOpen||!field.atHome)return;if(!round.undo())$('warnings').textContent='Undo needs the refunded resources back. Gather more first.';else changed();};
function clearHighlight(){for(const mesh of highlight){view.scene.remove(mesh);mesh.geometry.dispose();mesh.material.dispose();}highlight=[];}
function problem(cell){if(!cell)return;const pos=cellPosition(cell),o=new T.Mesh(new T.BoxGeometry(8.1,.18,8.1),new T.MeshBasicMaterial({color:0xff604c,transparent:true,opacity:.6,depthTest:false}));o.position.set(pos.x,pos.y+.2,pos.z);view.scene.add(o);highlight.push(o);view.refresh();}
