$('check').onclick=check;
async function end(){if(checking||round.phase!=='build')return;const result=await check();round.finish(!!result?.ok);showBlueprint(true);if(round.phase==='showcase'){const score=assessCastle(round.layout,config),total=Math.round(score.score*.85+15);$('result').innerHTML=`<h3>${total}/100  /  ${score.cosmeticRank}</h3><p>85% composition estimate + 15% verified routes.</p>`;for(const cat of score.categories){const p=document.createElement('p');p.textContent=`${cat.label}: ${cat.score}/${cat.max}. ${cat.detail}`;$('result').append(p);}const p=document.createElement('p');p.textContent='Silhouette/composition, integrated trees/houses/courts, related heights and proportions, clear approaches and focal core are bounded local rules. Your taste remains the final judge.';$('result').append(p);}else if(round.phase==='trial')await beginTrial();else $('result').textContent='Invalid construction at deadline: round failed. Your exact design and resource balance remain available for retry. Nothing was placed or repaired.';update();}
