$('mode').onchange=()=>{if(round.phase==='build')round.mode=$('mode').value;};$('new').onclick=()=>{if(checking)return;cleanActors();round=new Round({mode:$('mode').value,seconds:+$('duration').value});field.reset();fieldNotice='Jump off your dock to claim and link a camp.';closeBlueprint();$('result').textContent='Empty plot. Start with a connected court, arrival and core; optional gates must connect.';changed();};$('retry').onclick=()=>{if(checking)return;cleanActors();round.retry();field.reset();fieldNotice='Jump off your dock to claim and link a camp.';closeBlueprint();$('result').textContent='Same design and resource balance; fresh build timer. Repairs are yours to make.';changed();};$('save').onclick=()=>{try{localStorage.setItem(KEY,JSON.stringify({layout:round.layout,stock:round.stock,mode:round.mode,duration:round.duration}));$('warnings').textContent='Saved only in Castle Trials storage.';}catch{$('warnings').textContent='Storage unavailable; this visit still works.';}};
