$('export-design').onclick=async()=>{if(exportChecking)return;exportChecking=true;$('export-design').disabled=true;try{const exported=exportDesign(round.layout);$('export-status').textContent='Checking this design against the copied Wave import rules...';const compatibility=await checkWaveCompatibility(exported.design);$('export-status').textContent=waveCompatibilityText(compatibility)+` Exported snapshot: ${exported.design.layout.length} pieces (${exported.bytes} bytes); no resources/timer/camps.`;const url=URL.createObjectURL(new Blob([exported.text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='castle-trials-design.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('export-status').textContent='Export refused: '+e.message;}finally{exportChecking=false;$('export-design').disabled=false;}};
const load=document.createElement('button');load.textContent='Load saved design';$('save').after(load);load.onclick=()=>{if(checking)return;try{const data=JSON.parse(localStorage.getItem(KEY));if(!data)throw Error('No saved design.');if(!Array.isArray(data.layout)||data.layout.length>432||!Array.isArray(data.stock)||data.stock.length!==2||!data.stock.every(n=>Number.isFinite(n)&&n>=0&&n<100000))throw Error('Invalid saved design.');assertTrialsPieces(data.layout);construction.preview(0,data.layout,config).dispose();if(data.layout.some(p=>!COSTS[p.type]||p.layer>2))throw Error('Unavailable saved part.');cleanActors();round=new Round({mode:data.mode==='trial'?'trial':'showcase',seconds:data.duration===120?120:1200});round.layout=data.layout;round.stock=data.stock;field.reset();fieldNotice='Jump off your dock to claim and link a camp.';closeBlueprint();changed();}catch(e){$('warnings').textContent=e.message;}};
function makePhysics(start){const built=construction.preview(0,round.layout,config),physics=flightWorld(built.colliders,[{...start,r:2}]);physics.built=built;return physics;}
