$('walk').onclick=async()=>{if(round.phase==='trial')return;if(walking){stopWalk();return;}const result=await check();if(!result?.ok)return;walkPhysics=makePhysics(cellPosition(round.layout.find(p=>p.type==='spawn')));walking=true;actor.visible=true;view.focusCell(round.layout.find(p=>p.type==='spawn'));$('walk').textContent='Back to building';view.fit();};
async function beginTrial(){trialPreparing=true;await new Promise(resolve=>requestAnimationFrame(resolve));stopWalk();const start=cellPosition(round.layout.find(p=>p.type==='spawn')),route=validation.routes.find(p=>p.id==='core').points;walkPhysics=makePhysics(start);walking=true;actor.visible=true;for(const p of round.layout)delete p.cooldown;coreHP=300;trialTime=0;weapons=new TrialWeapons(view.root,walkPhysics.built.colliders,(a,b)=>trace(a,b));view.focusCell(round.layout.find(p=>p.type==='core'));for(let i=0;i<3;i++){const sprite=actor.clone();sprite.visible=false;sprite.material=sprite.material.clone();sprite.material.color.set(0xeab7d4);view.scene.add(sprite);enemies.push({sprite,hp:100,physics:makePhysics(start),route,index:1,delay:i*3,attack:0});}$('result').textContent='Three raiders enter through your arrival court. WASD moves; Space strikes within 5m with clear sight. Paid bows, cannons, armed towers and trebuchets fire automatically; stone arcs collide and explode. Protect the core.';trialPreparing=false;}
