const keys=new Set();window.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;keys.add(e.code);if(blueprintOpen&&['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
