const gridDetails=document.createElement('details');gridDetails.innerHTML='<summary>Precise plot grid  /  accessible placement</summary>';const grid=document.createElement('div');grid.className='plot-grid';gridDetails.append(grid);$('cost').after(gridDetails);function drawGrid(){if(!grid)return;grid.replaceChildren();for(let z=0;z<12;z++)for(let x=0;x<12;x++){const p=round.layout.find(p=>p.x===x&&p.z===z&&p.layer===+$('layer').value),b=document.createElement('button');b.textContent=p?PARTS.find(t=>t.id===p.type)?.symbol||' / ':' / ';b.title=b.ariaLabel=`Plot ${x},${z}: ${p?.type||'empty'}`;b.onclick=()=>{if(walking||checking||!blueprintOpen||!field.atHome)return;try{const cell={x,z,layer:+$('layer').value};if($('piece').value==='erase')round.erase(cell);else round.place({...cell,type:$('piece').value,rotation:+$('rotation').value});changed();}catch(e){$('warnings').textContent=e.message;}};grid.append(b);}}changed();
